cat << 'EOF' > .git/hooks/pre-push
#!/usr/bin/env node
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');
const os = require('os');

if (isMainThread) {
    console.log("========================================");
    console.log(" PRE-PUSH HOOK: CPU BENCHMARK SUITE");
    console.log("========================================");

    const cores = os.cpus().length;
    console.log(`[*] Detected ${cores} available cores.`);
    console.log("[*] Maximizing parallelism...");

    // High iteration count for statistical significance
    const iterations = 500000000; 
    const numTasks = cores * 4; // Multiple tasks per core
    console.log(`[*] Running ${numTasks} tasks with ${iterations.toLocaleString()} iterations each...`);

    const start = Date.now();
    let completed = 0;

    for (let i = 0; i < numTasks; i++) {
        const worker = new Worker(__filename, { workerData: iterations });
        worker.on('message', () => {
            completed++;
            if (completed === numTasks) {
                const elapsed = (Date.now() - start) / 1000;
                console.log(`[*] CPU benchmark suite completed in ${elapsed.toFixed(3)} seconds.`);
                console.log("========================================\n");
                process.exit(0);
            }
        });
        worker.on('error', (err) => {
            console.error(err);
            process.exit(1);
        });
    }
} else {
    // Worker thread workload
    const limit = workerData;
    let total = 0;
    // CPU-bound loop
    for (let i = 0; i < limit; i++) {
        total += Math.sqrt(i);
    }
    parentPort.postMessage(total);
}
EOF

chmod +x .git/hooks/pre-push

